import Foundation

// Firmware only reads databases up to the version it shipped with (SysInfoExtended "DBVersion"),
// so an iPod whose database was written by newer software shows no music at all. This is the
// layout an empty library of that older generation has; ids and timestamps are filled in per use.
enum ITunesDBTemplate {
    private static let emptyBase64 = ""

    // Largest version for which the dataset layout of the template is valid.
    static let maximumVersion: UInt32 = 0x19

    static func emptyDatabase(version: UInt32, now: Date = Date()) throws -> ITunesDBDocument {
        guard version <= maximumVersion, let bytes = Data(base64Encoded: emptyBase64) else {
            throw ITunesDBError.unsupported("no empty database layout for version 0x\(String(version, radix: 16))")
        }
        let document = try ITunesDBDocument(data: bytes)
        let root = document.root
        let databaseID = UInt64.random(in: 1...UInt64.max)
        let secondaryID = UInt64.random(in: 1...UInt64.max)
        let masterID = UInt64.random(in: 1...UInt64.max)
        let stamp = UInt32(truncatingIfNeeded: Int64(now.timeIntervalSince1970 + 2_082_844_800))

        root.header.writeLE(version, at: 0x10)
        root.header.writeLE(databaseID, at: 0x18)
        root.header.writeLE(secondaryID, at: 0x24)
        root.header.writeLE(databaseID, at: 0x48)
        for dataset in root.children where dataset.magic == "mhsd" {
            for playlist in dataset.children.first?.children ?? [] where playlist.magic == "mhyp" {
                playlist.header.writeLE(stamp, at: 0x18)
                playlist.header.writeLE(masterID, at: 0x1C)
                playlist.header.writeLE(secondaryID, at: 0x3C)
                playlist.header.writeLE(masterID, at: 0x44)
            }
        }
        // The standard browse lists the firmware expects on a master playlist; filled on write.
        for master in document.masterPlaylists() {
            for sortType: UInt32 in [0x03, 0x05, 0x04, 0x07, 0x12] {
                master.children.append(ITunesDBDocument.libraryIndexMHOD(sortType: sortType))
                master.children.append(ITunesDBDocument.jumpTableMHOD(sortType: sortType))
            }
        }
        return document
    }
}
